package com.osrsalgo.runelite;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import org.junit.After;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;

/** BackendClient owns HTTP I/O + the offline queue. Tests use OkHttp's
 *  MockWebServer so no real network and no real backend needed. */
public class BackendClientTest
{
    @Rule public TemporaryFolder tmp = new TemporaryFolder();
    private MockWebServer server;
    private BackendClient client;
    private Path queueFile;

    @Before public void setUp() throws Exception {
        server = new MockWebServer();
        server.start();
        queueFile = tmp.newFile("queue.jsonl").toPath();
        client = new BackendClient(
            new OkHttpClient(), new com.google.gson.Gson(),
            server.url("/").toString(),
            queueFile, 10);
    }

    @After public void tearDown() throws Exception { server.shutdown(); }

    private GeEventPayload samplePayload() {
        return GeEventPayload.builder()
            .pluginLifecycleId("uuid-1")
            .slotIndex(0).itemId(11212).itemName("Dragonstone bolts (e)")
            .side("buy").status("pending")
            .totalQuantity(11000).filledQuantity(0).price(379)
            .avgFillPrice(null).spent(0)
            .eventTs("2026-06-27T15:00:00Z")
            .build();
    }

    @Test
    public void successfulPostReturnsOrderId() throws Exception {
        server.enqueue(new MockResponse().setResponseCode(200)
            .setBody("{\"order_id\":42,\"created\":true}"));
        Long orderId = client.postEvent(samplePayload());
        assertEquals(Long.valueOf(42L), orderId);
        assertEquals(1, server.getRequestCount());
    }

    @Test
    public void singleAttemptFailureReturnsNullAndQueues() throws Exception {
        // One failed call → null returned, payload appended to queue.
        server.enqueue(new MockResponse().setSocketPolicy(
            okhttp3.mockwebserver.SocketPolicy.DISCONNECT_AT_START));
        Long orderId = client.postEvent(samplePayload());
        assertNull(orderId);
        assertEquals(1, server.getRequestCount());   // exactly one attempt
        java.util.List<String> lines = Files.readAllLines(queueFile);
        assertEquals(1, lines.size());
        assertTrue(lines.get(0).contains("\"plugin_lifecycle_id\":\"uuid-1\""));
    }

    @Test
    public void drainQueueRePostsAndClearsOnSuccess() throws Exception {
        // Seed: a single queued event from a prior session.
        String seeded = new com.google.gson.Gson().toJson(samplePayload());
        Files.write(queueFile, java.util.Collections.singletonList(seeded));
        server.enqueue(new MockResponse().setResponseCode(200)
            .setBody("{\"order_id\":99}"));
        int drained = client.drainQueue();
        assertEquals(1, drained);
        assertEquals(0, Files.readAllLines(queueFile).size());
    }

    @Test
    public void drainFailureLeavesEventOnQueue() throws Exception {
        String seeded = new com.google.gson.Gson().toJson(samplePayload());
        Files.write(queueFile, java.util.Collections.singletonList(seeded));
        server.enqueue(new MockResponse().setSocketPolicy(
            okhttp3.mockwebserver.SocketPolicy.DISCONNECT_AT_START));
        int drained = client.drainQueue();
        assertEquals(0, drained);
        // Event still on disk.
        assertEquals(1, Files.readAllLines(queueFile).size());
    }

    @Test
    public void queueRespectsHardCapByDroppingOldest() throws Exception {
        // Cap is 10 in the @Before setup.
        java.util.List<String> lines = new java.util.ArrayList<>();
        for (int i = 0; i < 10; i++) {
            lines.add("{\"plugin_lifecycle_id\":\"old-" + i + "\"}");
        }
        Files.write(queueFile, lines);
        // Force one more append via a failing post.
        server.enqueue(new MockResponse().setSocketPolicy(
            okhttp3.mockwebserver.SocketPolicy.DISCONNECT_AT_START));
        client.postEvent(samplePayload());
        java.util.List<String> after = Files.readAllLines(queueFile);
        assertEquals(10, after.size());
        assertFalse(after.get(0).contains("old-0"));   // oldest dropped
        assertTrue(after.get(9).contains("uuid-1"));   // new one is last
    }

    @Test
    public void reconcileParsesMatchesMap() throws Exception {
        server.enqueue(new MockResponse().setResponseCode(200).setBody(
            "{\"matches\":{\"3\":{\"order_id\":42,\"plugin_lifecycle_id\":\"uuid-X\"}}}"));
        ReconcileRequest req = new ReconcileRequest(java.util.Collections.singletonList(
            new ReconcileRequest.Slot(3, 11212, "buy", 11000, 379, 0)));
        java.util.Map<Integer, BackendClient.ReconciledSlot> matches = client.reconcile(req);
        assertEquals(1, matches.size());
        assertEquals(Long.valueOf(42L), matches.get(3).getOrderId());
        assertEquals("uuid-X", matches.get(3).getPluginLifecycleId());
    }
}

package com.osrsalgo.runelite;

import org.junit.Test;
import static org.junit.Assert.*;

/** SlotTracker is pure — no network, no client API. Tests pin the
 *  UUID lifecycle invariants (created on EMPTY → active, retained
 *  during fills, dropped on EMPTY). */
public class SlotTrackerTest
{
    @Test
    public void newSlotGetsFreshUuid() {
        SlotTracker t = new SlotTracker();
        SlotState s = t.onActivity(3, "pending", 0);
        assertNotNull(s.getPluginLifecycleId());
        assertNull(s.getBackendOrderId());
        assertEquals(0, s.getLastQuantitySold());
        assertEquals("pending", s.getLastStatus());
    }

    @Test
    public void subsequentActivityKeepsSameUuid() {
        SlotTracker t = new SlotTracker();
        String firstUuid = t.onActivity(3, "pending", 0).getPluginLifecycleId();
        String secondUuid = t.onActivity(3, "partial", 5000).getPluginLifecycleId();
        assertEquals(firstUuid, secondUuid);
    }

    @Test
    public void emptyDropsTheSlot() {
        SlotTracker t = new SlotTracker();
        String firstUuid = t.onActivity(3, "pending", 0).getPluginLifecycleId();
        t.onEmpty(3);
        // Next activity on the same slot → fresh UUID, fresh state.
        String thirdUuid = t.onActivity(3, "pending", 0).getPluginLifecycleId();
        assertNotEquals(firstUuid, thirdUuid);
        assertEquals(thirdUuid, t.get(3).getPluginLifecycleId());
    }

    @Test
    public void differentSlotsGetDifferentUuids() {
        SlotTracker t = new SlotTracker();
        String a = t.onActivity(0, "pending", 0).getPluginLifecycleId();
        String b = t.onActivity(5, "pending", 0).getPluginLifecycleId();
        assertNotEquals(a, b);
    }

    @Test
    public void rehydrateInstallsUuidForExistingSlot() {
        SlotTracker t = new SlotTracker();
        t.rehydrate(3, "uuid-from-reconcile", 42L);
        SlotState s = t.get(3);
        assertEquals("uuid-from-reconcile", s.getPluginLifecycleId());
        assertEquals(Long.valueOf(42L), s.getBackendOrderId());
    }

    @Test
    public void rememberBackendOrderIdUpdatesExistingSlot() {
        SlotTracker t = new SlotTracker();
        t.onActivity(3, "pending", 0);
        t.rememberOrderId(3, 99L);
        assertEquals(Long.valueOf(99L), t.get(3).getBackendOrderId());
    }
}

package com.osrsalgo.runelite;

import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;
import static org.junit.Assert.*;

public class OsrsAlgoPluginTest
{
    @Test public void buyingZeroFilledIsPending() {
        assertEquals("pending", OsrsAlgoPlugin.mapStatus(GrandExchangeOfferState.BUYING, 100, 0));
    }
    @Test public void buyingPartialIsPartial() {
        assertEquals("partial", OsrsAlgoPlugin.mapStatus(GrandExchangeOfferState.BUYING, 100, 50));
    }
    @Test public void boughtIsFilled() {
        assertEquals("filled", OsrsAlgoPlugin.mapStatus(GrandExchangeOfferState.BOUGHT, 100, 100));
    }
    @Test public void cancelledBuyIsCancelled() {
        assertEquals("cancelled", OsrsAlgoPlugin.mapStatus(GrandExchangeOfferState.CANCELLED_BUY, 100, 30));
    }
    @Test public void sideFromBoughtIsBuy() {
        assertEquals("buy", OsrsAlgoPlugin.mapSide(GrandExchangeOfferState.BOUGHT));
    }
    @Test public void sideFromSoldIsSell() {
        assertEquals("sell", OsrsAlgoPlugin.mapSide(GrandExchangeOfferState.SOLD));
    }
    @Test public void sideFromEmptyIsNull() {
        assertNull(OsrsAlgoPlugin.mapSide(GrandExchangeOfferState.EMPTY));
    }
}

package com.osrsalgo.runelite;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

/** User-tunable settings exposed in Runelite's config dialog. */
@ConfigGroup("osrsAlgo")
public interface OsrsAlgoConfig extends Config
{
    @ConfigItem(
        keyName = "backendUrl",
        name = "Backend URL",
        description = "Base URL of the Flask backend that ingests GE events"
    )
    default String backendUrl() { return "http://127.0.0.1:5000"; }

    @ConfigItem(
        keyName = "enabled",
        name = "Send events",
        description = "When off, GE events are observed but NOT posted (debug mode)"
    )
    default boolean enabled() { return true; }
}

package com.osrsalgo.runelite;

import com.google.inject.Provides;
import java.awt.Color;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.ItemComposition;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.client.RuneLite;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import com.google.gson.Gson;
import okhttp3.OkHttpClient;

@Slf4j
@PluginDescriptor(
    name = "OSRS Algo (GE log)",
    description = "Auto-logs Grand Exchange activity to the OSRS Algo backend",
    tags = {"ge", "grand exchange", "flipping", "algo"}
)
public class OsrsAlgoPlugin extends Plugin
{
    private static final int MAX_QUEUE_LINES = 10_000;
    private static final long DRAIN_INTERVAL_SEC = 30;

    @Inject private OsrsAlgoConfig config;
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ItemManager itemManager;
    @Inject private OkHttpClient httpClient;
    @Inject private Gson gson;
    @Inject private ClientToolbar clientToolbar;
    @Inject private EventBus eventBus;

    private final SlotTracker tracker = new SlotTracker();
    private BackendClient backend;
    private ScheduledExecutorService scheduler;
    private OsrsAlgoPanel panel;
    private NavigationButton navButton;
    private EventBus.Subscriber geSubscriber;

    @Override
    protected void startUp() throws Exception
    {
        Path pluginDir = RuneLite.RUNELITE_DIR.toPath().resolve("osrs-algo");
        Files.createDirectories(pluginDir);
        Path queueFile = pluginDir.resolve("queue.jsonl");
        backend = new BackendClient(httpClient, gson, config.backendUrl(),
            queueFile, MAX_QUEUE_LINES);
        panel = new OsrsAlgoPanel();
        panel.setStatus("ready", Color.GREEN);
        navButton = NavigationButton.builder()
            .tooltip("OSRS Algo")
            .icon(ImageUtil.loadImageResource(getClass(), "icon.png"))
            .priority(5)
            .panel(panel)
            .build();
        clientToolbar.addNavigation(navButton);
        // Manual EventBus registration because @Subscribe relies on a
        // LambdaMetafactory teleport into the plugin's classloader, which
        // fails for sideloaded plugins (PluginClassLoader doesn't
        // implement PrivateLookupableClassLoader). Registering a method
        // reference here creates the lambda in OUR classloader, sidestepping
        // the teleport. See Runelite ReflectUtil.installLookupHelper Javadoc.
        geSubscriber = eventBus.register(GrandExchangeOfferChanged.class,
            this::onGrandExchangeOfferChanged, 0f);
        scheduler = Executors.newSingleThreadScheduledExecutor(
            r -> new Thread(r, "osrs-algo-drain"));
        scheduler.scheduleWithFixedDelay(this::drainOnce,
            DRAIN_INTERVAL_SEC, DRAIN_INTERVAL_SEC, TimeUnit.SECONDS);
        clientThread.invokeLater(this::reconcileOnStartup);
        log.info("OSRS Algo plugin started — backend={}", config.backendUrl());
    }

    @Override
    protected void shutDown()
    {
        if (navButton != null) clientToolbar.removeNavigation(navButton);
        // Unregister our manual subscription via the Subscriber token returned
        // at registration. The manual register() path stores the Consumer as
        // the Subscriber's "object", so unregister(Object) with `this` would
        // not match — we must use the Subscriber overload instead.
        eventBus.unregister(geSubscriber);
        if (scheduler != null) scheduler.shutdownNow();
        log.info("OSRS Algo plugin stopped");
    }

    public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged ev)
    {
        if (!config.enabled()) return;
        int slot = ev.getSlot();
        GrandExchangeOffer offer = ev.getOffer();
        if (offer.getState() == GrandExchangeOfferState.EMPTY) {
            tracker.onEmpty(slot);
            return;
        }
        sendForSlot(slot, offer);
    }

    private void sendForSlot(int slot, GrandExchangeOffer offer)
    {
        String status = mapStatus(offer.getState(), offer.getTotalQuantity(),
            offer.getQuantitySold());
        String side = mapSide(offer.getState());
        if (side == null) return;
        SlotState state = tracker.onActivity(slot, status, offer.getQuantitySold());
        ItemComposition def = itemManager.getItemComposition(offer.getItemId());
        Double avg = offer.getQuantitySold() > 0
            ? offer.getSpent() / (double) offer.getQuantitySold() : null;
        GeEventPayload payload = GeEventPayload.builder()
            .pluginLifecycleId(state.getPluginLifecycleId())
            .slotIndex(slot)
            .itemId(offer.getItemId())
            .itemName(def != null ? def.getName() : "")
            .side(side).status(status)
            .totalQuantity(offer.getTotalQuantity())
            .filledQuantity(offer.getQuantitySold())
            .price(offer.getPrice())
            .avgFillPrice(avg)
            .spent(offer.getSpent())
            .eventTs(Instant.now().toString())
            .build();
        Long orderId = backend.postEvent(payload);
        if (orderId != null) tracker.rememberOrderId(slot, orderId);
        if (panel != null) {
            panel.setLastEvent("Last event: " + side + " "
                + (def != null ? def.getName() : "#" + offer.getItemId())
                + " (" + status + ")");
            panel.setStatus(orderId != null ? "ok" : "queued",
                orderId != null ? Color.GREEN : Color.ORANGE);
        }
    }

    private void reconcileOnStartup()
    {
        if (!config.enabled()) return;
        java.util.List<ReconcileRequest.Slot> slots = new java.util.ArrayList<>();
        GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
        for (int i = 0; i < offers.length; i++) {
            GrandExchangeOffer offer = offers[i];
            if (offer == null || offer.getState() == GrandExchangeOfferState.EMPTY) continue;
            String side = mapSide(offer.getState());
            if (side == null) continue;
            slots.add(new ReconcileRequest.Slot(i, offer.getItemId(), side,
                offer.getTotalQuantity(), offer.getPrice(), offer.getQuantitySold()));
        }
        if (slots.isEmpty()) return;
        java.util.Map<Integer, BackendClient.ReconciledSlot> matches =
            backend.reconcile(new ReconcileRequest(slots));
        for (java.util.Map.Entry<Integer, BackendClient.ReconciledSlot> e : matches.entrySet()) {
            tracker.rehydrate(e.getKey(), e.getValue().getPluginLifecycleId(),
                e.getValue().getOrderId());
        }
        // For every active slot (matched or not), fire a synthetic update so
        // the backend learns the CURRENT state — if it's matched, this updates
        // the existing order; if not, it creates a new one with the fresh UUID.
        for (int i = 0; i < offers.length; i++) {
            GrandExchangeOffer offer = offers[i];
            if (offer == null || offer.getState() == GrandExchangeOfferState.EMPTY) continue;
            sendForSlot(i, offer);
        }
    }

    private void drainOnce()
    {
        try {
            int drained = backend.drainQueue();
            if (panel != null && drained > 0) {
                panel.setStatus("ok", Color.GREEN);
            }
        } catch (Exception e) {
            log.warn("scheduled drain failed: {}", e.getMessage());
            if (panel != null) panel.setStatus("backend down", Color.RED);
        }
    }

    @Provides
    OsrsAlgoConfig provideConfig(ConfigManager cm) { return cm.getConfig(OsrsAlgoConfig.class); }

    // ---- pure helpers (tested in OsrsAlgoPluginTest) ----

    /** Pure function: map Runelite's OfferState + offer numbers into our
     *  internal status string. Extracted so it's trivially unit-testable
     *  without instantiating a Client. */
    static String mapStatus(GrandExchangeOfferState state, int totalQty, int sold)
    {
        switch (state) {
            case BUYING:
            case SELLING:
                return sold > 0 && sold < totalQty ? "partial"
                     : sold == 0 ? "pending"
                     : "filled";   // odd case — fully sold but state hasn't flipped yet
            case BOUGHT:
            case SOLD:
                return "filled";
            case CANCELLED_BUY:
            case CANCELLED_SELL:
                return "cancelled";
            case EMPTY:
            default:
                return "empty";
        }
    }

    /** Pure: derive 'buy' vs 'sell' from the state. EMPTY returns null
     *  (caller should not be posting for empty slots). */
    static String mapSide(GrandExchangeOfferState state)
    {
        switch (state) {
            case BUYING: case BOUGHT: case CANCELLED_BUY: return "buy";
            case SELLING: case SOLD: case CANCELLED_SELL: return "sell";
            default: return null;
        }
    }
}

package com.osrsalgo.runelite;

import com.google.gson.annotations.SerializedName;
import java.util.List;
import lombok.Value;

/** Wire shape for POST /api/ge-events/reconcile. */
@Value
public class ReconcileRequest
{
    List<Slot> slots;

    @Value
    public static class Slot
    {
        @SerializedName("slot_index")     int slotIndex;
        @SerializedName("item_id")        int itemId;
                                          String side;
        @SerializedName("total_quantity") int totalQuantity;
                                          int price;
        @SerializedName("filled_quantity") int filledQuantity;
    }
}

package com.osrsalgo.runelite;

import lombok.Value;

/** Per-slot in-memory state held by SlotTracker. Immutable — updates
 *  produce a fresh instance. */
@Value
public class SlotState
{
    String pluginLifecycleId;   // UUID assigned by the plugin
    Long backendOrderId;        // null until the first POST returns success
    int lastQuantitySold;       // last observed quantitySold (informational; backend handles idempotency)
    String lastStatus;          // last observed status (informational)
}

package com.osrsalgo.runelite;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.nio.file.Path;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;

/** Thin HTTP wrapper for the Flask backend. Owns the offline queue.
 *  File I/O is serialized via fileLock; HTTP work runs without any
 *  lock so the client thread isn't blocked during a drain. */
@Slf4j
public class BackendClient
{
    private static final MediaType JSON = MediaType.parse("application/json");

    private final OkHttpClient http;
    private final Gson gson;
    private final String baseUrl;
    private final Path queueFile;
    private final int maxQueueLines;
    private final Object fileLock = new Object();

    public BackendClient(OkHttpClient http, Gson gson, String baseUrl, Path queueFile,
                         int maxQueueLines)
    {
        this.http = http;
        this.gson = gson;
        this.baseUrl = baseUrl.endsWith("/") ? baseUrl.substring(0, baseUrl.length() - 1) : baseUrl;
        this.queueFile = queueFile;
        this.maxQueueLines = maxQueueLines;
    }

    /** Returns the backend order_id on success, null on failure (event
     *  is queued for later drain). One HTTP attempt only — retries
     *  happen via the scheduled drain timer in OsrsAlgoPlugin, which
     *  uses a ScheduledExecutorService (Plugin Hub policy: no
     *  Thread.sleep, no Thread.interrupt). */
    public Long postEvent(GeEventPayload payload)
    {
        Long orderId = postEventInternal(payload);
        if (orderId == null) {
            // Single attempt failed — queue for the next scheduled drain.
            appendToQueue(payload);
        }
        return orderId;
    }

    /** Returns the count of events successfully re-posted. File I/O is
     *  serialized via fileLock; HTTP work runs without any lock so a
     *  concurrent postEvent() from the client thread isn't blocked.
     *  Events appended during drain are preserved by re-reading the
     *  queue before the rewrite. */
    public int drainQueue()
    {
        java.util.List<String> queued;
        synchronized (fileLock) {
            try {
                queued = java.nio.file.Files.exists(queueFile)
                    ? new java.util.ArrayList<>(java.nio.file.Files.readAllLines(queueFile))
                    : java.util.Collections.emptyList();
            } catch (IOException e) {
                log.warn("queue read failed: {}", e.getMessage());
                return 0;
            }
        }
        if (queued.isEmpty()) return 0;

        java.util.Set<String> succeededLines = new java.util.HashSet<>();
        int succeeded = 0;
        for (String line : queued) {
            GeEventPayload payload;
            try {
                payload = gson.fromJson(line, GeEventPayload.class);
            } catch (Exception e) {
                log.warn("skipping malformed queued event: {}", e.getMessage());
                succeededLines.add(line);   // remove unparseable junk too
                continue;
            }
            Long orderId = postEventInternal(payload);
            if (orderId != null) {
                succeeded++;
                succeededLines.add(line);
            }
        }

        // Rewrite the file: re-read (so any concurrent appendToQueue is
        // preserved), drop the lines we successfully processed, write back.
        synchronized (fileLock) {
            try {
                java.util.List<String> current = java.nio.file.Files.exists(queueFile)
                    ? new java.util.ArrayList<>(java.nio.file.Files.readAllLines(queueFile))
                    : new java.util.ArrayList<>();
                current.removeAll(succeededLines);
                java.nio.file.Files.write(queueFile, current);
            } catch (IOException e) {
                log.warn("queue rewrite failed: {}", e.getMessage());
            }
        }
        return succeeded;
    }

    /** Single-attempt POST. Returns order_id on 2xx, null on any
     *  failure (IO, non-2xx, parse error). Used by both postEvent
     *  (which queues on null) and drainQueue (which leaves the line
     *  in the queue on null). */
    private Long postEventInternal(GeEventPayload payload)
    {
        String json = gson.toJson(payload);
        Request req = new Request.Builder()
            .url(baseUrl + "/api/ge-events")
            .post(RequestBody.create(JSON, json))
            .build();
        try (Response resp = http.newCall(req).execute()) {
            if (resp.isSuccessful()) {
                String body = resp.body() != null ? resp.body().string() : "{}";
                return new JsonParser().parse(body).getAsJsonObject()
                    .get("order_id").getAsLong();
            }
            log.warn("ge-events POST got HTTP {}", resp.code());
        } catch (IOException e) {
            log.warn("ge-events POST IO error: {}", e.getMessage());
        }
        return null;
    }

    private void appendToQueue(GeEventPayload payload)
    {
        synchronized (fileLock) {
            try {
                java.util.List<String> current = java.nio.file.Files.exists(queueFile)
                    ? new java.util.ArrayList<>(java.nio.file.Files.readAllLines(queueFile))
                    : new java.util.ArrayList<>();
                current.add(gson.toJson(payload));
                // Cap at maxQueueLines — drop from the head if we exceed it.
                while (current.size() > maxQueueLines) {
                    current.remove(0);
                    log.warn("queue cap reached — oldest event dropped");
                }
                java.nio.file.Files.write(queueFile, current);
            } catch (IOException e) {
                log.error("queue append failed: {}", e.getMessage());
            }
        }
    }

    @lombok.Value
    public static class ReconciledSlot
    {
        Long orderId;
        String pluginLifecycleId;
    }

    /** Called once on plugin startup. Posts the current state of every
     *  non-EMPTY GE slot; backend returns which ones map to existing
     *  open plugin orders. Failures return empty (caller proceeds as
     *  if no slots matched — fresh UUIDs on next event). */
    public java.util.Map<Integer, ReconciledSlot> reconcile(ReconcileRequest body)
    {
        String json = gson.toJson(body);
        Request req = new Request.Builder()
            .url(baseUrl + "/api/ge-events/reconcile")
            .post(RequestBody.create(JSON, json))
            .build();
        try (Response resp = http.newCall(req).execute()) {
            if (!resp.isSuccessful()) {
                log.warn("reconcile got HTTP {}", resp.code());
                return java.util.Collections.emptyMap();
            }
            String text = resp.body() != null ? resp.body().string() : "{}";
            JsonObject parsed = new JsonParser().parse(text).getAsJsonObject();
            JsonObject matches = parsed.has("matches") && parsed.get("matches").isJsonObject()
                ? parsed.getAsJsonObject("matches") : new JsonObject();
            java.util.Map<Integer, ReconciledSlot> out = new java.util.HashMap<>();
            for (java.util.Map.Entry<String, com.google.gson.JsonElement> e : matches.entrySet()) {
                JsonObject m = e.getValue().getAsJsonObject();
                out.put(Integer.parseInt(e.getKey()),
                    new ReconciledSlot(m.get("order_id").getAsLong(),
                                       m.get("plugin_lifecycle_id").getAsString()));
            }
            return out;
        } catch (IOException e) {
            log.warn("reconcile network error: {}", e.getMessage());
            return java.util.Collections.emptyMap();
        }
    }
}

package com.osrsalgo.runelite;

import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

/** Tracks per-slot lifecycle state in memory. One instance per plugin
 *  lifetime; cleared on plugin shutdown.
 *
 *  Invariants:
 *  - A slot's UUID is generated lazily the first time we see activity
 *    on it after EMPTY (or after the tracker is created).
 *  - The UUID survives across partial / filled / cancelled states; it
 *    is only discarded when the slot goes EMPTY (i.e. user collected
 *    the items / GP and a new offer can now occupy the slot).
 *  - rehydrate() seeds a slot from the reconcile response, so the
 *    first event after plugin restart can update the right backend
 *    order instead of creating a duplicate. */
public class SlotTracker
{
    private final Map<Integer, SlotState> bySlot = new HashMap<>();

    public synchronized SlotState onActivity(int slotIndex, String status, int quantitySold)
    {
        SlotState existing = bySlot.get(slotIndex);
        String uuid = existing != null
            ? existing.getPluginLifecycleId()
            : UUID.randomUUID().toString();
        Long orderId = existing != null ? existing.getBackendOrderId() : null;
        SlotState next = new SlotState(uuid, orderId, quantitySold, status);
        bySlot.put(slotIndex, next);
        return next;
    }

    public synchronized void onEmpty(int slotIndex)
    {
        bySlot.remove(slotIndex);
    }

    public synchronized SlotState get(int slotIndex)
    {
        return bySlot.get(slotIndex);
    }

    public synchronized void rehydrate(int slotIndex, String lifecycleId, long orderId)
    {
        bySlot.put(slotIndex, new SlotState(lifecycleId, orderId, 0, "pending"));
    }

    public synchronized void rememberOrderId(int slotIndex, long orderId)
    {
        SlotState s = bySlot.get(slotIndex);
        if (s == null) return;
        bySlot.put(slotIndex, new SlotState(
            s.getPluginLifecycleId(), orderId,
            s.getLastQuantitySold(), s.getLastStatus()
        ));
    }
}

package com.osrsalgo.runelite;

import com.google.gson.annotations.SerializedName;
import lombok.Builder;
import lombok.Value;

/** Wire shape for POST /api/ge-events. Field names use SerializedName
 *  to keep snake_case on the wire (matches the Flask convention) while
 *  keeping camelCase here. */
@Value
@Builder
public class GeEventPayload
{
    @SerializedName("plugin_lifecycle_id") String pluginLifecycleId;
    @SerializedName("slot_index")          int slotIndex;
    @SerializedName("item_id")             int itemId;
    @SerializedName("item_name")           String itemName;
                                           String side;            // "buy" | "sell"
                                           String status;          // pending/partial/filled/cancelled
    @SerializedName("total_quantity")      int totalQuantity;
    @SerializedName("filled_quantity")     int filledQuantity;
                                           int price;
    @SerializedName("avg_fill_price")      Double avgFillPrice;    // nullable
                                           long spent;
    @SerializedName("event_ts")            String eventTs;         // ISO-8601 UTC
}

package com.osrsalgo.runelite;

import java.awt.*;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.PluginPanel;

/** Minimal status panel — one dot + one-liner. Updated via
 *  setStatus() / setLastEvent() from the plugin thread; Swing methods
 *  bounce to the EDT internally. */
public class OsrsAlgoPanel extends PluginPanel
{
    private final JLabel statusDot   = new JLabel("●");
    private final JLabel statusText  = new JLabel("starting up");
    private final JLabel lastEvent   = new JLabel(" ");

    public OsrsAlgoPanel()
    {
        setBorder(new EmptyBorder(10, 10, 10, 10));
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        statusDot.setFont(statusDot.getFont().deriveFont(24f));
        statusDot.setForeground(Color.GRAY);
        JPanel head = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 0));
        head.add(statusDot); head.add(statusText);
        add(head);
        lastEvent.setFont(lastEvent.getFont().deriveFont(11f));
        add(lastEvent);
    }

    public void setStatus(String label, Color color)
    {
        SwingUtilities.invokeLater(() -> {
            statusDot.setForeground(color);
            statusText.setText(label);
        });
    }

    public void setLastEvent(String line)
    {
        SwingUtilities.invokeLater(() -> lastEvent.setText(line));
    }

}
